import os
base = r"c:\ideaProject\demo1\miniprogram"

def W(rel, s):
    p = os.path.join(base, rel)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f:
        f.write(s.strip() + '\n')
    print('  ' + rel)

WXS = '\n<wxs module="img" src="../../utils/image.wxs" />\n'

