W("pages/checkout/checkout.js", """var api=require('../../utils/api');Page({data:{mode:'cart',orderId:null,cartItems:[],totalAmount:0,address:null,receiverName:'',receiverPhone:'',shippingAddress:'',remark:''},onLoad:function(opts){if(opts.orderId)this.setData({mode:'pay',orderId:parseInt(opts.orderId)});var t=this;if(this.data.mode==='cart'){api.getCart().then(function(r){var items=(r.data||[]).filter(function(i){return i.selected!==0;});var total=0;items.forEach(function(i){total+=(i.productPrice||0)*(i.quantity||1);});t.setData({cartItems:items,totalAmount:total.toFixed(2)});}).catch(function(){});}api.getDefaultAddr().then(function(r){var addr=r.data;if(addr)t.setData({address:addr,receiverName:addr.receiverName,receiverPhone:addr.receiverPhone,shippingAddress:addr.region+' '+addr.detailAddress});}).catch(function(){});},chooseAddr:function(){wx.navigateTo({url:'/pages/address/address?mode=select'});},onRemark:function(e){this.setData({remark:e.detail.value});},submitOrder:function(){var d=this.data;if(!d.shippingAddress){wx.showToast({title:'请选择地址',icon:'none'});return;}if(d.mode==='pay'){api.payOrder(d.orderId,'alipay').then(function(){wx.showToast({title:'支付成功',icon:'success'});setTimeout(function(){wx.switchTab({url:'/pages/order/order'});},1000);}).catch(function(e){wx.showToast({title:e.message||'支付失败',icon:'none'});});return;}var items=d.cartItems.map(function(i){return{productId:i.productId,productName:i.productName,productImage:i.productImage,price:i.productPrice,quantity:i.quantity};});var total=parseFloat(d.totalAmount);api.createOrder({totalAmount:total,actualAmount:total,shippingFee:0,discountAmount:0,shippingAddress:d.shippingAddress,receiverName:d.receiverName,receiverPhone:d.receiverPhone,remark:d.remark,items:items}).then(function(){wx.showToast({title:'下单成功',icon:'success'});setTimeout(function(){wx.switchTab({url:'/pages/order/order'});},1000);}).catch(function(e){wx.showToast({title:e.message||'下单失败',icon:'none'});});}});""")
