W("pages/address-edit/address-edit.js", """var api=require('../../utils/api');Page({data:{id:0,receiverName:'',receiverPhone:'',region:'',detailAddress:'',isDefault:0},onLoad:function(opts){if(opts.id&&opts.id!=='0')this.setData({id:parseInt(opts.id)});},onName:function(e){this.setData({receiverName:e.detail.value});},onPhone:function(e){this.setData({receiverPhone:e.detail.value});},onRegion:function(e){this.setData({region:e.detail.value});},onDetail:function(e){this.setData({detailAddress:e.detail.value});},setDefault:function(e){this.setData({isDefault:e.detail.value?1:0});},save:function(){var d=this.data;if(!d.receiverName||!d.receiverPhone||!d.region||!d.detailAddress){wx.showToast({title:'请填写完整',icon:'none'});return;}api.saveAddress({id:d.id||null,receiverName:d.receiverName,receiverPhone:d.receiverPhone,region:d.region,detailAddress:d.detailAddress,isDefault:d.isDefault}).then(function(){wx.showToast({title:'保存成功',icon:'success'});setTimeout(function(){wx.navigateBack();},1000);}).catch(function(e){wx.showToast({title:e.message||'保存失败',icon:'none'});});}});""")
