# exchange-detail
W("pages/exchange-detail/exchange-detail.js", """var api=require('../../utils/api');Page({data:{order:null},onLoad:function(opts){var t=this;api.getExchangeList().then(function(r){var o=null;(r.data||[]).forEach(function(x){if(x.id===parseInt(opts.id))o=x;});if(o){o.statusLabel=['待确认','已确认','已完成','已取消','已拒绝'][o.status||0]||'未知';t.setData({order:o});}}).catch(function(){});},confirm:function(){var t=this,oid=this.data.order.id;api.confirmExchange(oid).then(function(){wx.showToast({title:'已确认',icon:'success'});t.onLoad({id:oid});});},reject:function(){var t=this,oid=this.data.order.id;api.rejectExchange(oid).then(function(){wx.showToast({title:'已拒绝',icon:'none'});t.onLoad({id:oid});});},cancel:function(){var t=this,oid=this.data.order.id;api.cancelExchange(oid).then(function(){wx.navigateBack();});}});""")
W("pages/exchange-detail/exchange-detail.wxml", WXS+"""<view class="page-wrap"><view wx:if="{{!order}}" class="empty-state"><text>加载中...</text></view><block wx:if="{{order}}"><view style="background:#fff;padding:30rpx;margin-bottom:20rpx;"><view style="display:flex;justify-content:space-between;align-items:center;"><text style="font-size:32rpx;font-weight:bold;">交换详情</text><text class="status-tag status-{{order.status}}">{{order.statusLabel}}</text></view><view style="font-size:24rpx;color:#999;margin-top:8rpx;">{{order.orderNo}}</view><view style="font-size:26rpx;color:#666;margin-top:8rpx;">差价：{{order.priceDifference||0}} 元</view></view><view style="padding:30rpx;display:flex;gap:16rpx;"><button wx:if="{{order.status===0}}" class="btn-primary" style="flex:1;height:72rpx;line-height:72rpx;font-size:28rpx;margin:0;" bindtap="confirm">确认交换</button><button wx:if="{{order.status===0}}" class="btn-ghost" style="flex:1;height:72rpx;line-height:72rpx;font-size:28rpx;margin:0;" bindtap="reject">拒绝</button><button wx:if="{{order.status===0||order.status===1}}" class="btn-ghost" style="flex:1;height:72rpx;line-height:72rpx;font-size:28rpx;margin:0;" bindtap="cancel">取消交换</button></view></block></view>""")

# refund
W("pages/refund/refund.js", """var api=require('../../utils/api');Page({data:{orderId:0,reason:''},onLoad:function(opts){if(opts.orderId)this.setData({orderId:parseInt(opts.orderId)});},onReason:function(e){this.setData({reason:e.detail.value});},submit:function(){var t=this;api.applyRefund(t.data.orderId).then(function(){wx.showToast({title:'退款已提交',icon:'success'});setTimeout(function(){wx.navigateBack();},1000);}).catch(function(e){wx.showToast({title:e.message||'提交失败',icon:'none'});});}});""")
W("pages/refund/refund.wxml", WXS+"""<view class="page-wrap" style="padding:30rpx;"><view style="background:#fff;border-radius:16rpx;padding:30rpx;"><view style="font-size:28rpx;font-weight:bold;margin-bottom:20rpx;">申请退款</view><textarea placeholder="请描述退款原因" value="{{reason}}" bindinput="onReason" style="width:100%;height:200rpx;border:1rpx solid #f0f0f0;border-radius:8rpx;padding:16rpx;font-size:26rpx;"/><button class="btn-primary" bindtap="submit" style="margin-top:30rpx;">提交申请</button></view></view>""")

# reviews
W("pages/reviews/reviews.js", """var api=require('../../utils/api');Page({data:{productId:0,rating:5,content:''},onLoad:function(opts){if(opts.productId)this.setData({productId:parseInt(opts.productId)});},setRating:function(e){this.setData({rating:parseInt(e.currentTarget.dataset.r)});},onContent:function(e){this.setData({content:e.detail.value});},submit:function(){var d=this.data;if(!d.content){wx.showToast({title:'请填写评价',icon:'none'});return;}api.submitReview(d.productId,{rating:d.rating,content:d.content}).then(function(){wx.showToast({title:'评价成功',icon:'success'});setTimeout(function(){wx.navigateBack();},1000);}).catch(function(e){wx.showToast({title:e.message||'评价失败',icon:'none'});});}});""")
W("pages/reviews/reviews.wxml", WXS+"""<view class="page-wrap" style="padding:30rpx;"><view style="background:#fff;border-radius:16rpx;padding:30rpx;"><view style="font-size:28rpx;font-weight:bold;margin-bottom:20rpx;">写评价</view><view style="display:flex;gap:12rpx;margin-bottom:20rpx;"><text wx:for="{{[1,2,3,4,5]}}" wx:key="*this" data-r="{{item}}" bindtap="setRating" style="font-size:44rpx;{{item<=rating?'color:#ffa502;':'color:#ddd;'}}">★</text></view><textarea placeholder="分享您的使用感受" value="{{content}}" bindinput="onContent" style="width:100%;height:200rpx;border:1rpx solid #f0f0f0;border-radius:8rpx;padding:16rpx;font-size:26rpx;"/><button class="btn-primary" bindtap="submit" style="margin-top:30rpx;">提交评价</button></view></view>""")

# feedback
W("pages/feedback/feedback.js", """var api=require('../../utils/api');Page({data:{content:'',contact:''},onContent:function(e){this.setData({content:e.detail.value});},onContact:function(e){this.setData({contact:e.detail.value});},submit:function(){var d=this.data;if(!d.content){wx.showToast({title:'请填写内容',icon:'none'});return;}api.submitFeedback({content:d.content,contact:d.contact}).then(function(){wx.showToast({title:'感谢反馈!',icon:'success'});setTimeout(function(){wx.navigateBack();},1000);}).catch(function(e){wx.showToast({title:e.message||'提交失败',icon:'none'});});}});""")
W("pages/feedback/feedback.wxml", WXS+"""<view class="page-wrap" style="padding:30rpx;"><view style="background:#fff;border-radius:16rpx;padding:30rpx;"><view style="font-size:28rpx;font-weight:bold;margin-bottom:20rpx;">意见反馈</view><textarea placeholder="请描述您遇到的问题或建议" value="{{content}}" bindinput="onContent" style="width:100%;height:240rpx;border:1rpx solid #f0f0f0;border-radius:8rpx;padding:16rpx;font-size:26rpx;"/><input placeholder="联系方式（选填）" value="{{contact}}" bindinput="onContact" style="height:80rpx;border-bottom:1rpx solid #f0f0f0;font-size:26rpx;margin-top:20rpx;"/><button class="btn-primary" bindtap="submit" style="margin-top:30rpx;">提交反馈</button></view></view>""")

print("Done! All 12 pages completed.")
